decode.code:
const [opcode, a, b, c] = bytes;
const addr = (b << 8) | c;
const badRegister = (n: number): DecodeResult => ({ ok: false, error: `R${n} is not a register (R0-R3)` });
const badAddress: DecodeResult = { ok: false, error: `address ${hex(addr)} is outside memory` };

switch (opcode) {
  case OPCODES.NOP:
    return { ok: true, instruction: { op: "NOP" } };
  case OPCODES.IRET:
    return { ok: true, instruction: { op: "IRET" } };
  case OPCODES.HALT:
    return { ok: true, instruction: { op: "HALT" } };
  case OPCODES.LOAD:
  case OPCODES.STORE:
    if (!isRegister(a)) return badRegister(a);
    if (addr >= MEMORY_SIZE) return badAddress;
    return { ok: true, instruction: { op: opcode === OPCODES.LOAD ? "LOAD" : "STORE", reg: a, address: addr } };
  case OPCODES.ADD:
  case OPCODES.SUB:
    if (!isRegister(a)) return badRegister(a);
    if (!isRegister(b)) return badRegister(b);
    return { ok: true, instruction: { op: opcode === OPCODES.ADD ? "ADD" : "SUB", reg: a, src: b } };
  case OPCODES.JMP:
  case OPCODES.JZ:
  case OPCODES.JNZ: {
    if (addr >= MEMORY_SIZE) return badAddress;
    const op = opcode === OPCODES.JMP ? "JMP" : opcode === OPCODES.JZ ? "JZ" : "JNZ";
    return { ok: true, instruction: { op, address: addr } };
  }
  case OPCODES.LOADI:
    if (!isRegister(a)) return badRegister(a);
    return { ok: true, instruction: { op: "LOADI", reg: a, value: c } };
  default:
    return { ok: false, error: `unknown opcode ${hex(opcode, 2)}` };
}

encode.code:
const opcode = OPCODES[instruction.op];
switch (instruction.op) {
  case "NOP":
  case "IRET":
  case "HALT":
    return [opcode, 0, 0, 0];
  case "LOAD":
  case "STORE":
    return [opcode, instruction.reg, instruction.address >> 8, instruction.address & 0xff];
  case "ADD":
  case "SUB":
    return [opcode, instruction.reg, instruction.src, 0];
  case "JMP":
  case "JZ":
  case "JNZ":
    return [opcode, 0, instruction.address >> 8, instruction.address & 0xff];
  case "LOADI":
    return [opcode, instruction.reg, 0, instruction.value];
}
